export const PLANNER_WINDOW_RADIUS_MINUTES = 10;
export const MINUTES_PER_DAY = 24 * 60;
export const MINIMUM_COMPARISON_DATES = 4;
export const MINIMUM_COMPARISON_CANDIDATES = 3;

export type WeekdayEvidence = Readonly<{
  labelDate: string;
  labelMinute: number;
}>;

// biome-ignore lint/style/useConsistentTypeDefinitions: AGENTS.md prefers types unless extending.
type PlannerStateBase = {
  candidateCount: number;
  historicalDateCount: number;
  selectedDateCount: number;
};

export type VisitPlan =
  | (PlannerStateBase & { state: "no-weekday-history" })
  | (PlannerStateBase & { state: "zero-selected-matches" })
  | (PlannerStateBase & { state: "insufficient-comparison" })
  | (PlannerStateBase & {
      candidateScores: number[];
      signal: "better" | "typical" | "quieter";
      state: "comparative";
    });

export function calculateVisitPlan(
  evidence: readonly WeekdayEvidence[],
  selectedMinute: number
): VisitPlan {
  const distinctEvidence = getDistinctEvidence(evidence);
  const historicalDateCount = new Set(
    distinctEvidence.map(({ labelDate }) => labelDate)
  ).size;
  const candidateMinutes = Array.from(
    new Set(distinctEvidence.map(({ labelMinute }) => labelMinute))
  ).sort((first, second) => first - second);
  const selectedDateCount = scoreWindow(distinctEvidence, selectedMinute);
  const candidateScores = candidateMinutes.map((minute) =>
    scoreWindow(distinctEvidence, minute)
  );

  return calculatePlannerSignal({
    candidateScores,
    historicalDateCount,
    selectedDateCount,
  });
}

export function calculatePlannerSignal({
  candidateScores,
  historicalDateCount,
  selectedDateCount,
}: Readonly<{
  candidateScores: readonly number[];
  historicalDateCount: number;
  selectedDateCount: number;
}>): VisitPlan {
  const candidateCount = candidateScores.length;
  const base = {
    candidateCount,
    historicalDateCount,
    selectedDateCount,
  };

  if (historicalDateCount === 0) {
    return { ...base, state: "no-weekday-history" };
  }

  if (selectedDateCount === 0) {
    return { ...base, state: "zero-selected-matches" };
  }

  if (
    historicalDateCount < MINIMUM_COMPARISON_DATES ||
    candidateCount < MINIMUM_COMPARISON_CANDIDATES
  ) {
    return { ...base, state: "insufficient-comparison" };
  }

  const lowerScoreCount = candidateScores.filter(
    (candidateScore) => candidateScore < selectedDateCount
  ).length;
  const higherScoreCount = candidateScores.filter(
    (candidateScore) => candidateScore > selectedDateCount
  ).length;
  let signal: "better" | "typical" | "quieter" = "typical";
  if (3 * lowerScoreCount >= 2 * candidateCount) {
    signal = "better";
  } else if (3 * higherScoreCount >= 2 * candidateCount) {
    signal = "quieter";
  }

  return {
    ...base,
    candidateScores: [...candidateScores],
    signal,
    state: "comparative",
  };
}

function getDistinctEvidence(
  evidence: readonly WeekdayEvidence[]
): WeekdayEvidence[] {
  const seenEvidence = new Set<string>();
  const distinctEvidence: WeekdayEvidence[] = [];

  for (const entry of evidence) {
    const evidenceKey = `${entry.labelDate}\u0000${entry.labelMinute}`;
    if (seenEvidence.has(evidenceKey)) {
      continue;
    }

    seenEvidence.add(evidenceKey);
    distinctEvidence.push(entry);
  }

  return distinctEvidence;
}

function scoreWindow(
  evidence: readonly WeekdayEvidence[],
  centerMinute: number
): number {
  const windowStart = Math.max(0, centerMinute - PLANNER_WINDOW_RADIUS_MINUTES);
  const windowEnd = Math.min(
    MINUTES_PER_DAY - 1,
    centerMinute + PLANNER_WINDOW_RADIUS_MINUTES
  );
  const matchingDates = new Set<string>();

  for (const entry of evidence) {
    if (entry.labelMinute >= windowStart && entry.labelMinute <= windowEnd) {
      matchingDates.add(entry.labelDate);
    }
  }

  return matchingDates.size;
}
import { describe, expect, it } from "vitest";

import {
  calculatePlannerSignal,
  calculateVisitPlan,
  type WeekdayEvidence,
} from "@/lib/visit-planner";

const evidence = (labelDate: string, labelMinute: number): WeekdayEvidence => ({
  labelDate,
  labelMinute,
});

describe("calculateVisitPlan", () => {
  it("counts distinct dates in an inclusive ten-minute window", () => {
    const plan = calculateVisitPlan(
      [
        evidence("2026-08-03", 590),
        evidence("2026-08-03", 600),
        evidence("2026-08-10", 610),
        evidence("2026-08-17", 611),
      ],
      600
    );

    expect(plan).toMatchObject({
      candidateCount: 4,
      historicalDateCount: 3,
      selectedDateCount: 2,
      state: "insufficient-comparison",
    });
  });

  it("does not wrap matching windows across midnight", () => {
    const plan = calculateVisitPlan(
      [
        evidence("2026-08-03", 0),
        evidence("2026-08-10", 5),
        evidence("2026-08-17", 1439),
        evidence("2026-08-24", 1435),
      ],
      0
    );

    expect(plan).toMatchObject({
      historicalDateCount: 4,
      selectedDateCount: 2,
      state: "comparative",
    });
  });

  it("deduplicates date-minute evidence and candidate minutes but retains overlapping windows", () => {
    const plan = calculateVisitPlan(
      [
        evidence("2026-08-03", 600),
        evidence("2026-08-03", 600),
        evidence("2026-08-10", 605),
        evidence("2026-08-17", 605),
        evidence("2026-08-24", 610),
      ],
      605
    );

    expect(plan).toMatchObject({
      candidateCount: 3,
      historicalDateCount: 4,
      selectedDateCount: 4,
      state: "comparative",
    });
    if (plan.state !== "comparative") {
      return;
    }
    expect(plan.candidateScores).toEqual([4, 4, 4]);
  });

  it("is independent of evidence input order", () => {
    const sightings = [
      evidence("2026-08-03", 700),
      evidence("2026-08-10", 710),
      evidence("2026-08-17", 720),
      evidence("2026-08-24", 730),
    ];

    expect(calculateVisitPlan(sightings, 710)).toEqual(
      calculateVisitPlan([...sightings].reverse(), 710)
    );
  });

  it("uses no history, zero matches, then insufficient comparison as state precedence", () => {
    expect(calculateVisitPlan([], 600)).toMatchObject({
      selectedDateCount: 0,
      state: "no-weekday-history",
    });
    expect(
      calculateVisitPlan([evidence("2026-08-03", 600)], 900)
    ).toMatchObject({
      selectedDateCount: 0,
      state: "zero-selected-matches",
    });
    expect(
      calculateVisitPlan([evidence("2026-08-03", 600)], 600)
    ).toMatchObject({
      selectedDateCount: 1,
      state: "insufficient-comparison",
    });
  });

  it("requires four distinct historical dates and three distinct candidate minutes", () => {
    expect(
      calculateVisitPlan(
        [
          evidence("2026-08-03", 600),
          evidence("2026-08-10", 600),
          evidence("2026-08-17", 610),
          evidence("2026-08-24", 610),
        ],
        600
      )
    ).toMatchObject({
      candidateCount: 2,
      historicalDateCount: 4,
      state: "insufficient-comparison",
    });
    expect(
      calculateVisitPlan(
        [
          evidence("2026-08-03", 600),
          evidence("2026-08-10", 610),
          evidence("2026-08-17", 620),
        ],
        600
      )
    ).toMatchObject({
      candidateCount: 3,
      historicalDateCount: 3,
      state: "insufficient-comparison",
    });
  });

  it.each([
    { candidateScores: [1, 2, 3], selectedScore: 3, signal: "better" },
    { candidateScores: [1, 2, 3], selectedScore: 2, signal: "typical" },
    { candidateScores: [1, 2, 3], selectedScore: 1, signal: "quieter" },
    { candidateScores: [2, 2, 3], selectedScore: 3, signal: "better" },
    { candidateScores: [2, 2, 3], selectedScore: 2, signal: "typical" },
    { candidateScores: [1, 2, 2], selectedScore: 1, signal: "quieter" },
    { candidateScores: [2, 2, 2], selectedScore: 2, signal: "typical" },
    { candidateScores: [1, 2, 3, 4], selectedScore: 3, signal: "typical" },
    { candidateScores: [1, 2, 3, 4], selectedScore: 4, signal: "better" },
    { candidateScores: [1, 2, 3, 4], selectedScore: 2, signal: "typical" },
    { candidateScores: [1, 2, 3, 4], selectedScore: 1, signal: "quieter" },
    { candidateScores: [4, 3, 2, 1], selectedScore: 1, signal: "quieter" },
  ])("classifies $selectedScore among $candidateScores as $signal", ({
    candidateScores,
    selectedScore,
    signal,
  }) => {
    const plan = calculatePlannerSignal({
      candidateScores,
      historicalDateCount: 4,
      selectedDateCount: selectedScore,
    });

    expect(plan).toMatchObject({
      selectedDateCount: selectedScore,
      signal,
      state: "comparative",
    });
  });
});
import { createFileRoute } from "@tanstack/react-router";
import { useServerFn } from "@tanstack/react-start";
import { type ReactNode, useCallback, useEffect, useState } from "react";

import { BottomNavigation } from "@/components/bottom-navigation";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { listWeekdayEvidence } from "@/lib/sighting-functions";
import type { ListWeekdayEvidence } from "@/lib/sightings";
import {
  calculateVisitPlan,
  type VisitPlan,
  type WeekdayEvidence,
} from "@/lib/visit-planner";

export const Route = createFileRoute("/plan")({
  component: PlanRoute,
});

const WEEKDAYS = [
  "Sunday",
  "Monday",
  "Tuesday",
  "Wednesday",
  "Thursday",
  "Friday",
  "Saturday",
] as const;
const TIME_PATTERN = /^([01]\d|2[0-3]):([0-5]\d)$/;

// biome-ignore lint/style/useConsistentTypeDefinitions: AGENTS.md prefers types unless extending.
type PlanFields = {
  labelTime: string;
  weekday: number;
};

const getCurrentDeviceTime = (): Date => new Date();

function PlanRoute(): ReactNode {
  return <PlanPage />;
}

export function PlanPage(): ReactNode {
  const getWeekdayEvidence = useServerFn(listWeekdayEvidence);
  const listWeekdayEvidenceFromRoute = useCallback<ListWeekdayEvidence>(
    async (weekday) => await getWeekdayEvidence({ data: weekday }),
    [getWeekdayEvidence]
  );

  return <PlanForm listWeekdayEvidence={listWeekdayEvidenceFromRoute} />;
}

export function PlanForm({
  listWeekdayEvidence,
  now = getCurrentDeviceTime,
}: Readonly<{
  listWeekdayEvidence: ListWeekdayEvidence;
  now?: () => Date;
}>): ReactNode {
  const [fields, setFields] = useState<PlanFields>();
  const [errorMessage, setErrorMessage] = useState<string>();
  const [evidence, setEvidence] = useState<WeekdayEvidence[]>();
  const [evidenceWeekday, setEvidenceWeekday] = useState<number>();

  useEffect(() => {
    const currentTime = now();
    setFields({
      labelTime: formatTime(currentTime),
      weekday: currentTime.getDay(),
    });
  }, [now]);

  const selectedWeekday = fields?.weekday;

  useEffect(() => {
    if (selectedWeekday === undefined) {
      return;
    }

    let active = true;
    setEvidence(undefined);
    setEvidenceWeekday(undefined);
    setErrorMessage(undefined);
    const loadEvidence = async (): Promise<void> => {
      try {
        const result = await listWeekdayEvidence(selectedWeekday);
        if (!active) {
          return;
        }

        if (!result.ok) {
          setErrorMessage(result.message);
          return;
        }

        setEvidence(result.evidence);
        setEvidenceWeekday(selectedWeekday);
      } catch {
        if (active) {
          setErrorMessage("Unable to load planning evidence. Try again.");
        }
      }
    };

    loadEvidence().catch(() => {
      if (active) {
        setErrorMessage("Unable to load planning evidence. Try again.");
      }
    });
    return () => {
      active = false;
    };
  }, [listWeekdayEvidence, selectedWeekday]);

  if (!fields) {
    return <PlanLoadingFrame />;
  }

  const selectedMinute = labelTimeToMinute(fields.labelTime);
  const selectedEvidence =
    evidenceWeekday === fields.weekday ? evidence : undefined;
  const plan =
    selectedEvidence && selectedMinute !== undefined
      ? calculateVisitPlan(selectedEvidence, selectedMinute)
      : undefined;
  const isLoadingEvidence =
    selectedMinute !== undefined &&
    selectedEvidence === undefined &&
    !errorMessage;

  return (
    <div
      className="mx-auto flex min-h-screen w-full max-w-md flex-col px-4 py-8"
      data-testid="plan-page"
    >
      <header className="mb-8">
        <p className="font-medium text-muted-foreground text-sm">
          Chicken Tracking
        </p>
        <h1 className="mt-2 font-semibold text-4xl tracking-tight">Plan</h1>
        <p className="mt-2 text-muted-foreground">
          Compare a weekday and approximate time with your historical sightings.
        </p>
      </header>
      <Card>
        <CardHeader>
          <CardTitle>Visit plan</CardTitle>
        </CardHeader>
        <CardContent className="grid gap-6">
          <p className="text-muted-foreground">
            I&apos;m going {WEEKDAYS[fields.weekday]} around{" "}
            {formatPlannerTime(fields.labelTime)}.
          </p>
          <div className="grid gap-2">
            <Label htmlFor="plan-weekday">Weekday</Label>
            <select
              className="h-12 w-full rounded-md border border-input bg-background px-3 text-base outline-none focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50"
              id="plan-weekday"
              onChange={(event) => {
                setFields((current) =>
                  current
                    ? { ...current, weekday: Number(event.target.value) }
                    : current
                );
              }}
              value={fields.weekday}
            >
              {WEEKDAYS.map((weekday, index) => (
                <option key={weekday} value={index}>
                  {weekday}
                </option>
              ))}
            </select>
          </div>
          <div className="grid gap-2">
            <Label htmlFor="plan-time">Approximate time</Label>
            <Input
              className="h-12 text-base"
              id="plan-time"
              onChange={(event) => {
                setFields((current) =>
                  current
                    ? { ...current, labelTime: event.target.value }
                    : current
                );
              }}
              required
              type="time"
              value={fields.labelTime}
            />
          </div>
          {selectedMinute === undefined ? (
            <p className="text-destructive text-sm" role="alert">
              Choose a complete approximate time.
            </p>
          ) : null}
          {errorMessage ? <PlanFailure message={errorMessage} /> : null}
          {isLoadingEvidence ? (
            <output aria-live="polite">Loading historical sightings…</output>
          ) : null}
          {plan ? (
            <section
              aria-atomic="true"
              aria-live="polite"
              data-testid="planner-result"
            >
              <PlanResult plan={plan} />
            </section>
          ) : null}
        </CardContent>
      </Card>
      <BottomNavigation currentDestination="plan" />
    </div>
  );
}

function PlanFailure({ message }: Readonly<{ message: string }>): ReactNode {
  return (
    <section aria-labelledby="plan-unavailable-heading">
      <h2
        className="font-semibold text-2xl tracking-tight"
        id="plan-unavailable-heading"
      >
        Plan unavailable
      </h2>
      <p className="mt-3 text-destructive text-sm" role="alert">
        {message}
      </p>
      <p className="mt-3 text-muted-foreground text-sm">
        Planning evidence is unavailable.
      </p>
      <p className="mt-3 text-muted-foreground text-sm">
        Selected-window distinct-date count is unavailable.
      </p>
    </section>
  );
}

function PlanLoadingFrame(): ReactNode {
  return (
    <div className="mx-auto flex min-h-screen w-full max-w-md flex-col px-4 py-8">
      <header className="mb-8">
        <p className="font-medium text-muted-foreground text-sm">
          Chicken Tracking
        </p>
        <h1 className="mt-2 font-semibold text-4xl tracking-tight">Plan</h1>
      </header>
      <Card aria-busy="true">
        <CardHeader>
          <CardTitle>Visit plan</CardTitle>
        </CardHeader>
        <CardContent>
          <output aria-live="polite">Preparing Visit plan…</output>
        </CardContent>
      </Card>
      <BottomNavigation currentDestination="plan" />
    </div>
  );
}

}

function PlanResult({ plan }: Readonly<{ plan: VisitPlan }>): ReactNode {
  const countDescription = `Selected window: ${formatDateCount(plan.selectedDateCount)}.`;

  if (plan.state === "no-weekday-history") {
    return (
      <PlanState
        coaching="Record label times on this weekday to improve this Visit plan."
        countDescription={countDescription}
        heading="No history for this weekday"
      />
    );
  }

  if (plan.state === "zero-selected-matches") {
    return (
      <PlanState
        coaching="Record more label times to improve this Visit plan."
        countDescription={countDescription}
        heading="No matching sightings yet"
      />
    );
  }

  if (plan.state === "insufficient-comparison") {
    return (
      <PlanState
        coaching="Record more label times to improve this Visit plan."
        countDescription={countDescription}
        heading="Not enough history to compare yet"
      />
    );
  }

  const headingBySignal = {
    better: "One of the better times",
    quieter: "One of the quieter times",
    typical: "About typical",
  } as const;

  return (
    <section aria-labelledby="planner-signal-heading">
      <h2
        className="font-semibold text-2xl tracking-tight"
        id="planner-signal-heading"
      >
        {headingBySignal[plan.signal]}
      </h2>
      <p className="mt-3 text-muted-foreground text-sm">{countDescription}</p>
    </section>
  );
}

function PlanState({
  coaching,
  countDescription,
  heading,
}: Readonly<{
  coaching: string;
  countDescription: string;
  heading: string;
}>): ReactNode {
  return (
    <section aria-labelledby="planner-state-heading">
      <h2
        className="font-semibold text-2xl tracking-tight"
        id="planner-state-heading"
      >
        {heading}
      </h2>
      <p className="mt-3 text-muted-foreground text-sm">{countDescription}</p>
      <p className="mt-3 text-muted-foreground text-sm">{coaching}</p>
      <a
        className="mt-4 inline-flex h-12 items-center justify-center rounded-md bg-primary px-4 font-medium text-base text-primary-foreground outline-none transition-colors hover:bg-primary/90 focus-visible:ring-[3px] focus-visible:ring-ring/50"
        href="/"
      >
        Capture
      </a>
    </section>
  );
}

function formatDateCount(count: number): string {
  return `${count} distinct ${count === 1 ? "date" : "dates"}`;
}

function formatTime(date: Date): string {
  return `${date.getHours().toString().padStart(2, "0")}:${date
    .getMinutes()
    .toString()
    .padStart(2, "0")}`;
}

function labelTimeToMinute(labelTime: string): number | undefined {
  const match = TIME_PATTERN.exec(labelTime);
  if (!match) {
    return undefined;
  }

  return Number(match[1]) * 60 + Number(match[2]);
}

function formatPlannerTime(labelTime: string): string {
  const labelMinute = labelTimeToMinute(labelTime);
  if (labelMinute === undefined) {
    return labelTime;
  }

  const hour = Math.floor(labelMinute / 60);
  const minute = labelMinute % 60;
  const period = hour < 12 ? "AM" : "PM";
  const twelveHour = hour % 12 || 12;

  return `${twelveHour}:${minute.toString().padStart(2, "0")} ${period}`;
}
import { z } from "zod";

export const DONENESS_VALUES = ["light", "medium", "dark"] as const;
export type Doneness = (typeof DONENESS_VALUES)[number];

export const createSightingInputSchema = z.object({
  labelDate: z.iso.date(),
  labelMinute: z.int().min(0).max(1439),
});

export type CreateSightingInput = z.infer<typeof createSightingInputSchema>;

// biome-ignore lint/style/useConsistentTypeDefinitions: AGENTS.md prefers types unless extending.
export type Sighting = {
  createdAt: Date;
  doneness: Doneness | null;
  id: number;
  labelDate: string;
  labelMinute: number;
  updatedAt: Date;
