  | { kind: "not-found"; message: string; ok: false }
  | { kind: "unavailable"; message: string; ok: false };

export type UpdateSightingDoneness = (
  input: UpdateSightingDonenessInput
) => Promise<UpdateSightingDonenessResult>;

